def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    outside=set()
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==0 and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==0 and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==0 and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    interior={(r,c) for r in range(h) for c in range(w) if g[r][c]==0 and (r,c) not in outside}
    ones={(r,c) for r in range(h) for c in range(w) if g[r][c]==1}
    seen=set(); qualifying=set()
    for start in ones:
        if start in seen: continue
        comp=set([start]); seen.add(start); q=deque([start])
        while q:
            r,c=q.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(r+dr,c+dc)
                if p in ones and p not in seen:
                    seen.add(p); comp.add(p); q.append(p)
        touches_inside=any((r+dr,c+dc) in interior for r,c in comp for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
        if touches_inside: qualifying |= comp
    for r,c in qualifying:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==0:
                if (nr,nc) in interior: g[nr][nc]=3
                else: g[nr][nc]=2
    return g
'''
